// Record the owned 3D viewport only; preserve simulation and wall-clock timing separately.
using System;using System.IO;using System.Drawing;using System.Diagnostics;using System.Linq;using System.Runtime.InteropServices;using System.Text;using System.Text.Json;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
using ABB.Robotics.RobotStudio;using ABB.Robotics.RobotStudio.Stations;using ABB.Robotics.RobotStudio.Stations.Forms;
namespace MA6212.FinalRecording012 {
 public static class RecordingDecisions {
  public static bool MayStart(bool execute,bool context,bool ownedView,bool isolated,bool inputDefault,bool recorderStopped)=>execute&&context&&ownedView&&isolated&&inputDefault&&recorderStopped;
  public static (int width,int height,int maxWidth,int maxHeight) Dimensions(int width,int height){if(width<16||height<4||width>8192||height>8192)throw new InvalidDataException("Finite nonempty bounded viewport required");return (width/16*16,height/4*4,(width+15)/16*16,(height+15)/16*16);}
  public static long Missed(double elapsedMs,double nextDueMs,double periodMs)=>elapsedMs<nextDueMs?0:Math.Max(0,(long)Math.Floor((elapsedMs-nextDueMs)/periodMs));
 }
 public sealed class ManualViewRecorder {
  static ManualViewRecorder active; readonly GraphicControl view;readonly Station station;readonly int thread;readonly bool requireIsolation;readonly string boundHostDesktop;readonly int frameWidth,frameHeight,sourceWidth,sourceHeight,capWidth,capHeight;readonly StreamWriter log;readonly Stopwatch wall=new();readonly System.Windows.Forms.Timer timer=new();
  bool owns,stopping,stopped,capturing;long frames,missed;double nextDue;Task stopTask;public string Failure{get;private set;}="";public string VideoPath{get;}public string LogPath{get;}
  const double Period=125;
  [DllImport("kernel32.dll")]static extern uint GetCurrentThreadId();
  [DllImport("user32.dll")]static extern IntPtr GetThreadDesktop(uint id);
  [DllImport("user32.dll",SetLastError=true)]static extern IntPtr OpenInputDesktop(uint flags,bool inherit,uint access);
  [DllImport("user32.dll",SetLastError=true)]static extern bool CloseDesktop(IntPtr h);
  [DllImport("user32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool GetUserObjectInformation(IntPtr h,int index,StringBuilder text,uint length,out uint needed);
  [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint process);
  static string DesktopName(IntPtr h){var b=new StringBuilder(256);if(h==IntPtr.Zero||!GetUserObjectInformation(h,2,b,512,out _))throw new InvalidOperationException("Desktop identity unavailable");return b.ToString();}
  static void DesktopGuard(bool requireIsolatedDesktop,string boundHost){string current=DesktopName(GetThreadDesktop(GetCurrentThreadId()));if(!RecorderDesktopDecisions012.Allowed(false,boundHost,current,null))throw new InvalidOperationException("Recorder thread moved from its bound host desktop");if(!requireIsolatedDesktop)return;if(current!="MA6212_Isolated")throw new InvalidOperationException("Exact isolated thread desktop required");IntPtr h=OpenInputDesktop(0,false,1);try{if(!RecorderDesktopDecisions012.Allowed(true,boundHost,current,DesktopName(h)))throw new InvalidOperationException("Input desktop must stay Default");}finally{if(h!=IntPtr.Zero)CloseDesktop(h);}}
  static void ViewGuard(GraphicControl v,Station s,bool requireIsolatedDesktop,string boundHost){if(SynchronizationContext.Current is not WindowsFormsSynchronizationContext||v==null||s==null||s.Name!="MA6212_ElbowCell"||!ReferenceEquals(Station.ActiveStation,s)||!ReferenceEquals(Project.ActiveProject,s)||!ReferenceEquals(v.RootObject,s)||v.IsDisposed||!v.IsHandleCreated||v.InvokeRequired)throw new InvalidOperationException("Normal UI context and exact owned station GraphicControl required");GetWindowThreadProcessId(v.Handle,out uint pid);if(pid!=(uint)Environment.ProcessId)throw new InvalidOperationException("Target HWND is not this RobotStudio process");DesktopGuard(requireIsolatedDesktop,boundHost);}
  ManualViewRecorder(GraphicControl target,Station s,string path,bool requireIsolatedDesktop,string hostDesktop){requireIsolation=requireIsolatedDesktop;boundHostDesktop=hostDesktop;var dimensions=RecordingDecisions.Dimensions(target.ClientSize.Width,target.ClientSize.Height);frameWidth=dimensions.width;frameHeight=dimensions.height;capWidth=dimensions.maxWidth;capHeight=dimensions.maxHeight;sourceWidth=target.ClientSize.Width;sourceHeight=target.ClientSize.Height;view=target;station=s;thread=Environment.CurrentManagedThreadId;VideoPath=path;LogPath=path+".frames.jsonl";log=new StreamWriter(new FileStream(LogPath,FileMode.CreateNew,FileAccess.Write,FileShare.Read),new UTF8Encoding(false));log.AutoFlush=true;timer.Interval=125;timer.Tick+=Tick;}
  void Record(object o){log.WriteLine(JsonSerializer.Serialize(o));}
  public static async Task<ManualViewRecorder> StartAsync(bool execute,string path,GraphicControl target,bool fitViewOnce=false,bool requireIsolatedDesktop=true){
   if(!execute)throw new InvalidOperationException("ExecuteRecording=true required; default is no execution");var s=Station.ActiveStation;string hostDesktop=DesktopName(GetThreadDesktop(GetCurrentThreadId()));ViewGuard(target,s,requireIsolatedDesktop,hostDesktop);if(!RecordingDecisions.MayStart(execute,true,true,true,true,active==null&&ScreenRecorder.State==RecorderState.Stopped))throw new InvalidOperationException("A recorder already exists; never stop another owner");if(!ScreenRecorder.Enabled)throw new InvalidOperationException("Native recorder preconditions not met");if(!Path.IsPathRooted(path)||Path.GetExtension(path).ToLowerInvariant()!=".mp4"||!Directory.Exists(Path.GetDirectoryName(path))||File.Exists(path)||File.Exists(path+".frames.jsonl"))throw new InvalidDataException("New absolute MP4 in an existing directory required");
   RecordingDecisions.Dimensions(target.ClientSize.Width,target.ClientSize.Height);
   var codecs=ScreenRecorder.GetCompressors(ScreenRecorderFileFormat.Mp4);if(codecs.Length==0)throw new InvalidOperationException("No native MP4 compressor available");
   // Own an empty placeholder by exclusive creation before native sink opens the owned filename.
   using(var f=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None))f.Flush(true);
   var r=new ManualViewRecorder(target,s,path,requireIsolatedDesktop,hostDesktop);active=r;
   try{if(fitViewOnce){target.ViewAll(0f);target.Update();}ScreenRecorder.FileFormat=ScreenRecorderFileFormat.Mp4;ScreenRecorder.Compression=codecs[0].Name;ScreenRecorder.FrameRate=8;ScreenRecorder.MaxWidth=r.capWidth;ScreenRecorder.MaxHeight=r.capHeight;if(ScreenRecorder.MaxWidth<r.sourceWidth||ScreenRecorder.MaxHeight<r.sourceHeight)throw new InvalidOperationException("Native cap setters would scale down target viewport; refuse guessed dimensions");ScreenRecorder.IncludeMouseCursor=false;
    if(!ScreenRecorder.Start(path,target.Handle,false))throw new InvalidOperationException("Native manual Start returned false; no frame capture permitted");r.owns=true;r.wall.Start();r.nextDue=0;r.Record(new{kind="start",utc=DateTime.UtcNow,station=s.FileInfo?.FullName,targetHandle=target.Handle.ToInt64(),thread=r.thread,mode="MANUAL_GRAPHICCONTROL_BITMAP_ONLY",requireIsolatedDesktop,boundHostDesktop=hostDesktop,inputDesktopPolicy=requireIsolatedDesktop?"EXACT_DEFAULT_UNCHANGED":"NOT_FORCED_FOR_ORDINARY_MANUAL_USER",automatic=false,fps=8,viewClientWidth=target.ClientSize.Width,viewClientHeight=target.ClientSize.Height,requestedWidth=r.frameWidth,requestedHeight=r.frameHeight,nativeMaxWidth=ScreenRecorder.MaxWidth,nativeMaxHeight=ScreenRecorder.MaxHeight,nativeActualDimensions="NOT_EXPOSED_BY_PUBLIC_API_VERIFY_MP4_WITH_FFPROBE",pixelConversion="NONE_ALIGNMENT_CAP_FIX_ONLY",alignmentHypothesis="Unscaled native width floor16, height floor4; verify actual MP4 dimensions",codec=codecs[0].Name});r.Capture();r.timer.Start();return r;
   }catch(Exception e){r.Failure=e.ToString();try{r.Record(new{kind="start_failure",error=r.Failure,nativeOwned=r.owns});}catch{}if(!r.owns){r.stopped=true;r.timer.Dispose();r.log.Dispose();active=null;}else{await r.StopAsync();}throw;}
  }
  async void Tick(object sender,EventArgs e){if(stopping||stopped||capturing)return;capturing=true;try{Capture();}catch(Exception ex){Failure=ex.ToString();try{Record(new{kind="capture_failure",utc=DateTime.UtcNow,error=Failure});}catch{}try{await StopAsync();}catch(Exception stopError){Failure+="\n"+stopError;}}finally{capturing=false;}}
  void Capture(){if(Environment.CurrentManagedThreadId!=thread)throw new InvalidOperationException("Capture thread changed");ViewGuard(view,station,requireIsolation,boundHostDesktop);if(ScreenRecorder.State!=RecorderState.Recording)throw new InvalidOperationException("Owned native recorder is not Recording");double began=wall.Elapsed.TotalMilliseconds;if(began<nextDue)return;long skipped=RecordingDecisions.Missed(began,nextDue,Period);missed+=skipped;nextDue+=Period*(skipped+1);if(view.ClientSize.Width!=sourceWidth||view.ClientSize.Height!=sourceHeight||ScreenRecorder.MaxWidth<sourceWidth||ScreenRecorder.MaxHeight<sourceHeight)throw new InvalidOperationException("Target viewport resized after native encoder initialization");double simBefore=Simulator.CurrentTime;Bitmap bitmap=null;int actualWidth=0,actualHeight=0;string pixelFormat="";try{bitmap=view.ScreenShot(frameWidth,frameHeight);actualWidth=bitmap.Width;actualHeight=bitmap.Height;pixelFormat=bitmap.PixelFormat.ToString();if(actualWidth!=frameWidth||actualHeight!=frameHeight)throw new InvalidOperationException("Screenshot dimensions differ from native initialization dimensions");ScreenRecorder.AddFrame(bitmap);bitmap=null;}finally{bitmap?.Dispose();}frames++;Record(new{kind="frame_submitted",idx=frames,utc=DateTime.UtcNow,bitmapWidth=actualWidth,bitmapHeight=actualHeight,bitmapPixelFormat=pixelFormat,viewClientWidth=view.ClientSize.Width,viewClientHeight=view.ClientSize.Height,nativeMaxWidth=ScreenRecorder.MaxWidth,nativeMaxHeight=ScreenRecorder.MaxHeight,wallBeginMs=began,wallEndMs=wall.Elapsed.TotalMilliseconds,simulationBeginMs=simBefore,simulationEndMs=Simulator.CurrentTime,callerMissed=missed,nativeTotalFrames=ScreenRecorder.TotalFrames,nativeDroppedFrames=ScreenRecorder.DroppedFrames,nativeCurrentSeconds=ScreenRecorder.CurrentTime});}
  public Task StopAsync(){if(Environment.CurrentManagedThreadId!=thread)throw new InvalidOperationException("Stop must be on original normal UI thread");return stopTask??=StopCore();}
  async Task StopCore(){if(stopped)return;stopping=true;timer.Stop();try{if(owns){try{Record(new{kind="stop_requested",utc=DateTime.UtcNow,wallMs=wall.Elapsed.TotalMilliseconds,simulationMs=Simulator.CurrentTime,framesSubmitted=frames,callerMissed=missed,nativeTotalFrames=ScreenRecorder.TotalFrames,nativeDroppedFrames=ScreenRecorder.DroppedFrames,nativeCurrentSeconds=ScreenRecorder.CurrentTime});}catch(Exception logError){Failure+="\n"+logError;}await ScreenRecorder.StopAsync();owns=false;if(ScreenRecorder.State!=RecorderState.Stopped)throw new InvalidOperationException("Native stop did not settle Stopped");Record(new{kind="stopped",utc=DateTime.UtcNow,framesSubmitted=frames,callerMissed=missed,bytes=File.Exists(VideoPath)?new FileInfo(VideoPath).Length:0,scope="Native encoding ended; decode/frame/video-content validation still required"});}}catch(Exception e){Failure+="\n"+e;try{Record(new{kind="stop_failure",error=Failure});}catch{}throw;}finally{stopped=true;timer.Dispose();log.Dispose();if(ReferenceEquals(active,this))active=null;}}
 }
}
